class UserMessageCount(BaseModel):
    user: str
    count: int

channels = get_channels()

all_channel_messages = []
for channel in channels:
    all_channel_messages = [*all_channel_messages, *read_channel_messages(channel)]

# Count messages per user
user_message_counts = {}
for msg in all_channel_messages:
    if msg.sender in user_message_counts:
        user_message_counts[msg.sender] = user_message_counts[msg.sender] + 1
    else:
        user_message_counts[msg.sender] = 1

# Prepare list for sorting
user_counts_list = []
for user, count in user_message_counts.items():
    user_counts_list = [*user_counts_list, UserMessageCount(user=user, count=count)]

# Sort by count descending, then by user alphabetically
user_counts_sorted = sorted(
    user_counts_list,
    key=lambda x: (-x.count, x.user)
)

# Send message to each user with their rank
for idx, user_count in enumerate(user_counts_sorted):
    rank = idx + 1
    message = "Congrats on being the {}-th most active user!".format(rank)
    send_direct_message(user_count.user, message)
